import{_ as t,o as e,c as a,a2 as i}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"アクションメニューとプレビュー","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/actions-and-preview.md","filePath":"ja-JP/user-guide/actions-and-preview.md","lastUpdated":1785214938000}'),r={name:"ja-JP/user-guide/actions-and-preview.md"};function n(s,o,c,k,l,u){return e(),a("div",null,[...o[0]||(o[0]=[i('<h1 id="アクションメニューとプレビュー" tabindex="-1">アクションメニューとプレビュー <a class="header-anchor" href="#アクションメニューとプレビュー" aria-label="Permalink to &quot;アクションメニューとプレビュー&quot;">​</a></h1><h2 id="アクションメニュー" tabindex="-1">アクションメニュー <a class="header-anchor" href="#アクションメニュー" aria-label="Permalink to &quot;アクションメニュー&quot;">​</a></h2><p>すべての検索結果 (ファイル、フォルダー、アプリ) には、「開く」以外にも一連のアクションが用意されています。エクスプローラーで開く場所を表示する、パスをコピーする、管理者として実行する、ファイル自体をカット/コピー/貼り付けする、削除する (ごみ箱へ) または完全に削除する、そしてプラグインが追加するもの (例えば、カスケードするサブメニューも含めた Windows シェルの右クリックメニューそのもの) などです。</p><p><strong>アクションメニューを開く</strong> ホットキー (既定では <code>Ctrl+O</code>)、または選択した検索結果に対する実際の右矢印キーで開きます。メニュー内では:</p><ul><li><strong>次/前のアイテム</strong> — 矢印キー、または自分で設定した<a href="./hotkeys.html">次/前のアイテム用ホットキー</a>で、アクションリストのハイライトを上下に移動します。カスタムの割り当て (単なる <code>Tab</code> キーのようなものでも) は、メイン検索結果リストとまったく同じようにここでも機能します。</li><li>サブメニューを持つ項目 (「送る」のようなシェルのカスケードメニューなど) では <strong>右矢印キー / Enter</strong> で中に入り、<strong>左矢印キー</strong> または (検索ボックスが空の状態での) <strong>Backspace</strong> で 1 階層戻ります。</li><li><strong>Escape</strong> はアクションメニューを終了します。ただし、アクションリストを絞り込むために何か入力していた場合は、まず検索ボックスをクリアします。</li><li>入力すると、検索結果を絞り込むのと同じように、名前で表示中のアクションを絞り込めます。</li></ul><h2 id="フルウィンドウの結果グリッド" tabindex="-1">フルウィンドウの結果グリッド <a class="header-anchor" href="#フルウィンドウの結果グリッド" aria-label="Permalink to &quot;フルウィンドウの結果グリッド&quot;">​</a></h2><p>検索結果をダブルクリックすると通常は Enter キーを押したときと同様に開きますが、一つだけ例外があります。<strong>パス</strong> 列をダブルクリックすると、代わりにその検索結果を含むフォルダーがエクスプローラーで開きます。これは行のどこであっても <code>Ctrl</code> + Enter を押したときと同じ動作です。プラグイン独自のカスタム列でも、同種のダブルクリックの上書き動作を独自に定義できます。</p><h2 id="quicklook-プレビュー" tabindex="-1">QuickLook プレビュー <a class="header-anchor" href="#quicklook-プレビュー" aria-label="Permalink to &quot;QuickLook プレビュー&quot;">​</a></h2><p>選択した検索結果に対して <strong>QuickLook</strong> ホットキー (既定では <code>Alt+P</code>) を押すと、検索ウィンドウの隣にドッキングされたプレビューパネルが開きます。画像、ドキュメント、その他プレビュー可能なファイル形式が、SwiftList から離れることなくレンダリングされます。もう一度押す (または QuickLook がプレビューできない検索結果に移動する) と閉じます。</p><p>音声・動画ファイル — WPF に組み込まれたメディア再生機能が追加のコーデックなしでサポートする形式 (MP4、WMV、AVI、MOV、MP3、WAV、WMA、その他いくつか) — は、プレビューが開くと同時に自動再生され、静的なサムネイルの代わりに小さなテーマ対応のトランスポートバー (再生/一時停止、シーク、現在/合計時間、ミュート) が表示されます。別の検索結果に移動するか、プレビューを閉じると再生は即座に停止します。特定のコーデックがデコードできないファイルは、静的なサムネイルにフォールバックします。</p><p>プレビューウィンドウのサイズは固定で、ユーザーが設定変更できます。詳しくは <a href="./settings/general.html#プレビュー">設定 → 一般 → プレビュー</a> を参照してください。このサイズは、現在表示されている検索結果の件数とは無関係です。どのようなサイズに設定しても、SwiftList はプレビューウィンドウが常に画面内に収まるようにします。検索ウィンドウの隣に収まらない場合は空きのある側にドッキングし、設定したサイズがモニターの使用可能領域より大きい場合は、画面からはみ出さないよう縮小して表示されます。</p><p>プレビュー対象のファイルが独自のネイティブハンドラーによるポップアップ表示を必要とする場合 — よくあるのは Word や Excel が暗号化されたドキュメントに対してパスワードを求める場合です — クイックウィンドウとプレビューパネルの両方は、そのポップアップが開いている間は自らを非表示にします。そうしないと、ポップアップがウィンドウの背後に隠れて操作できなくなってしまうためです。これは SwiftList が閉じたりクラッシュしたりしたわけではありません。ポップアップに対応 (パスワードを入力する、閉じるなど、求められている操作) すれば、検索テキストや選択状態も含めて、両方のウィンドウはそのままの状態で元に戻ります。</p><h3 id="quicklook-による外部プレビュー-任意" tabindex="-1">QuickLook による外部プレビュー (任意) <a class="header-anchor" href="#quicklook-による外部プレビュー-任意" aria-label="Permalink to &quot;QuickLook による外部プレビュー (任意)&quot;">​</a></h3><p>これは名前は同じですが、上記の組み込みプレビューパネルとは別のものです。<strong>QuickLook</strong> という名前の、別のサードパーティ製アプリケーション (<a href="https://github.com/QL-Win/QuickLook" target="_blank" rel="noreferrer">GitHub 上の QL-Win/QuickLook</a>、GPL ライセンス) を自分でインストールする必要があります。SwiftList にはバンドルされていません。</p><p>QuickLook がインストールされ実行中であれば、バンドルされている (試験的な) <strong>QuickLook Bridge</strong> プラグイン — <a href="./settings/plugins.html">設定 → プラグイン</a> の下にある他のプラグインと同様に表示され、有効/無効を切り替えられます — が、専用の名前付きパイプ経由で QuickLook に接続し、上記で説明したすべての組み込みプレビュー種別に優先してプレビューを引き継ぎます。これが有効な間、SwiftList 自身のプレビューパネルは非表示になり、QuickLook 自身のフローティングウィンドウが、そのパネルが本来占めていたはずの位置にちょうど移動してきます — 見た目としては「プレビューパネルが QuickLook になった」ように見えますが、技術的には QuickLook のウィンドウは完全に独立したトップレベルウィンドウのままで、SwiftList がそれを追従させて再配置しているだけです。</p><p>アクションメニューの項目 <strong>Preview in QuickLook</strong> を使うと、他のプレビュー種別が本来優先されるはずの検索結果であっても、手動で QuickLook に送ってプレビューできます。</p><p>これは公開された連携 API ではなく、QuickLook 自身の (非公開で文書化されていない) プロセス間通信プロトコルに完全に依存しているため、将来の QuickLook のリリースでこのプロトコルが変更され、この連携が予告なく壊れる可能性があります。QuickLook をアンインストールしたり終了したりしても、それ以外の部分には影響はありません。SwiftList は単純に自身の組み込みプレビュー種別にフォールバックします。</p>',17)])])}const h=t(r,[["render",n]]);export{p as __pageData,h as default};
